window.AI9_DATA = window.AI9_DATA || {};
window.AI9_DATA.flashcards = [
  { id: "w1", deck: "AI Workloads", tag: "Workloads", front: "Anomaly detection", back: "<p><strong>Anomaly detection</strong> identifies data points that fall outside an established pattern or baseline, such as a fraudulent credit card charge or an unexpected spike in server latency.</p><p class=\"faint\">Exam trap: anomaly detection is about outliers against a baseline over time, not about grouping similar records together, which is clustering.</p>" },
  { id: "w2", deck: "AI Workloads", tag: "Workloads", front: "Computer vision workload", back: "<p><strong>Computer vision</strong> is an AI workload that enables machines to interpret and understand visual information from images and video, including classification, object detection, and OCR.</p><p class=\"faint\">Exam trap: computer vision and image processing are not the same; traditional image processing uses fixed algorithms, while computer vision uses trained models to derive meaning.</p>" },
  { id: "w3", deck: "AI Workloads", tag: "Workloads", front: "Natural language processing workload", back: "<p><strong>Natural language processing (NLP)</strong> is an AI workload that enables machines to understand, interpret, and generate human language, covering tasks like sentiment analysis, translation, and summarization.</p><p class=\"faint\">Exam trap: NLP covers written text; speech workloads convert audio to or from text first, then NLP techniques may be applied to the transcript.</p>" },
  { id: "w4", deck: "AI Workloads", tag: "Workloads", front: "Document intelligence workload", back: "<p><strong>Document intelligence</strong> (formerly Form Recognizer) is an AI workload that extracts structured data from documents such as invoices, receipts, and ID cards using prebuilt or custom models.</p><p class=\"faint\">Exam trap: document intelligence goes beyond plain OCR by understanding the structure and fields of a document; plain OCR just reads characters without semantic understanding.</p>" },
  { id: "w5", deck: "AI Workloads", tag: "Workloads", front: "Generative AI workload", back: "<p><strong>Generative AI</strong> is an AI workload that produces new content, such as text, images, or code, by learning patterns from training data, typically powered by large language models or diffusion models.</p><p class=\"faint\">Exam trap: generative AI creates new content; discriminative AI (classification, regression) predicts a label or value for existing input. Do not confuse them.</p>" },
  { id: "w6", deck: "AI Workloads", tag: "Workloads", front: "Knowledge mining workload", back: "<p><strong>Knowledge mining</strong> is an AI workload that uses AI enrichment skills to extract insights and structured information from large volumes of unstructured data such as documents, emails, and images, enabling search and discovery.</p><p class=\"faint\">Exam trap: Azure AI Search is the Azure service associated with knowledge mining; it ingests, enriches, and indexes content. Do not confuse it with Azure Cognitive Search (the former name).</p>" },
  { id: "w7", deck: "AI Workloads", tag: "Workloads", front: "Conversational AI workload", back: "<p><strong>Conversational AI</strong> is an AI workload that enables natural dialogue between users and machines through chatbots, virtual assistants, and voice interfaces, combining language understanding with dialog management.</p><p class=\"faint\">Exam trap: a conversational AI workload requires both language understanding (intent/entity recognition) and dialog flow management; a simple FAQ bot using only question answering is simpler and may not need full conversational AI.</p>" },
  { id: "w8", deck: "AI Workloads", tag: "Workloads", front: "Machine learning vs. artificial intelligence", back: "<p><strong>Artificial intelligence (AI)</strong> is the broad field of building systems that exhibit intelligent behavior; <strong>machine learning (ML)</strong> is a subset of AI where models learn patterns from data rather than being explicitly programmed with rules.</p><p class=\"faint\">Exam trap: all machine learning is AI, but not all AI is machine learning. Rule-based expert systems are AI but not ML.</p>" },
  { id: "w9", deck: "AI Workloads", tag: "Workloads", front: "Predictive workload", back: "<p>A <strong>predictive workload</strong> uses a trained machine learning model to forecast future values or classify new inputs based on historical patterns, such as predicting equipment failure or customer churn.</p><p class=\"faint\">Exam trap: prediction uses an existing trained model at inference time; training is a separate prior step. The exam may test whether a scenario describes training or inference.</p>" },
  { id: "w10", deck: "AI Workloads", tag: "Workloads", front: "Content moderation workload", back: "<p><strong>Content moderation</strong> is an AI workload that automatically detects offensive, unsafe, or policy-violating content in text and images, protecting users and platforms from harmful material.</p><p class=\"faint\">Exam trap: Azure AI Content Safety is the dedicated Azure service for content moderation; do not confuse it with general classification models that might incidentally detect categories.</p>" },
  { id: "w11", deck: "AI Workloads", tag: "Workloads", front: "Forecasting workload", back: "<p><strong>Forecasting</strong> is a predictive AI workload that predicts future numerical values over time, such as sales next month or energy demand tomorrow, using time-series models.</p><p class=\"faint\">Exam trap: forecasting is a form of regression applied to time-series data. It is not classification because it predicts a continuous value, not a discrete label.</p>" },
  { id: "w12", deck: "AI Workloads", tag: "Workloads", front: "Recommendation workload", back: "<p>A <strong>recommendation</strong> workload uses collaborative filtering, content-based filtering, or hybrid approaches to suggest relevant items (products, movies, articles) to a user based on behavior or preferences.</p><p class=\"faint\">Exam trap: recommendation is unsupervised or semi-supervised; it does not require explicit correct labels for every item-user pair, unlike supervised classification.</p>" },
  { id: "w13", deck: "AI Workloads", tag: "Workloads", front: "Speech workload", back: "<p>A <strong>speech workload</strong> converts audio to text (speech to text) or text to audio (text to speech) and may include speaker recognition or real-time translation of spoken language.</p><p class=\"faint\">Exam trap: speech-to-text and text-to-speech are separate capabilities; do not assume that a service that does one automatically does the other.</p>" },
  { id: "w14", deck: "AI Workloads", tag: "Workloads", front: "Translation workload", back: "<p>A <strong>translation workload</strong> converts text or speech from one natural language to another, such as English to French, using neural machine translation models.</p><p class=\"faint\">Exam trap: translation converts between languages; transliteration converts characters between scripts (e.g., Arabic text to Latin characters) without changing the language.</p>" },
  { id: "w15", deck: "AI Workloads", tag: "Workloads", front: "Anomaly detection vs. forecasting", back: "<p><strong>Anomaly detection</strong> flags unusual data points that deviate from a learned baseline; <strong>forecasting</strong> predicts what future values will be. Both use time-series data but answer different questions.</p><p class=\"faint\">Exam trap: if the scenario asks \"predict next month's sales,\" that is forecasting. If it asks \"alert when sales behavior is unusual,\" that is anomaly detection.</p>" },
  { id: "w16", deck: "AI Workloads", tag: "Workloads", front: "Conversational AI vs. question answering", back: "<p><strong>Conversational AI</strong> supports multi-turn dialogue with intent recognition and state management; <strong>question answering</strong> (Azure AI Language) matches a single user question to an answer in a knowledge base without managing dialog state.</p><p class=\"faint\">Exam trap: a simple FAQ bot built with Azure AI Language custom question answering is NOT the same as a full conversational AI system built with Azure AI Bot Service plus language understanding.</p>" },
  { id: "r1", deck: "Responsible AI", tag: "Fairness", front: "Fairness principle", back: "<p>The <strong>fairness</strong> principle of responsible AI requires that AI systems treat all people equitably and do not produce discriminatory outcomes based on characteristics such as gender, race, age, or disability.</p><p class=\"faint\">Exam trap: fairness is not about making every prediction identical for all groups; it is about ensuring that consequential outcomes (loans, hiring) are not systematically skewed by protected attributes.</p>" },
  { id: "r2", deck: "Responsible AI", tag: "Safety", front: "Reliability and safety principle", back: "<p>The <strong>reliability and safety</strong> principle requires AI systems to perform as intended across conditions, fail gracefully, and minimize risks of harm from unexpected inputs or system errors.</p><p class=\"faint\">Exam trap: reliability means the model behaves consistently and predictably; safety means it avoids causing harm. A model can be reliable (consistent) yet still unsafe if it consistently produces harmful outputs.</p>" },
  { id: "r3", deck: "Responsible AI", tag: "Privacy", front: "Privacy and security principle", back: "<p>The <strong>privacy and security</strong> principle requires that AI systems protect personal data throughout the model lifecycle, from data collection and training through deployment and inference.</p><p class=\"faint\">Exam trap: privacy in AI is not just about data storage; it also covers what a model may have memorized during training. Differential privacy is a technique used to address this during training.</p>" },
  { id: "r4", deck: "Responsible AI", tag: "Inclusiveness", front: "Inclusiveness principle", back: "<p>The <strong>inclusiveness</strong> principle requires AI systems to empower all people, including those with disabilities, and to consider diverse perspectives in design so no group is disadvantaged or excluded.</p><p class=\"faint\">Exam trap: inclusiveness extends beyond accessibility features; it also means involving diverse stakeholders in the design process so that edge cases affecting minority groups are not overlooked.</p>" },
  { id: "r5", deck: "Responsible AI", tag: "Transparency", front: "Transparency principle", back: "<p>The <strong>transparency</strong> principle requires that AI systems and their capabilities, limitations, and decision processes be understandable and clearly communicated to users and affected stakeholders.</p><p class=\"faint\">Exam trap: transparency does not require exposing proprietary model weights; it means users should understand what the system does, how confident it is, and what data it was trained on.</p>" },
  { id: "r6", deck: "Responsible AI", tag: "Accountability", front: "Accountability principle", back: "<p>The <strong>accountability</strong> principle requires that people, not AI systems, are ultimately responsible for decisions made with AI assistance, and that governance frameworks exist to audit and review AI behavior.</p><p class=\"faint\">Exam trap: accountability means humans remain in the loop for consequential decisions; it does not mean a single person is always blamed, but that clear ownership of AI outcomes is defined within an organization.</p>" },
  { id: "r7", deck: "Responsible AI", tag: "Fairness", front: "Fairness scenario example", back: "<p>A <strong>fairness scenario</strong> in AI occurs when a model produces different outcomes for different demographic groups in a way that causes harm, for example, a loan approval model that approves applications from one ethnic group at a lower rate despite similar creditworthiness.</p><p class=\"faint\">Exam trap: the exam may present a scenario and ask which responsible AI principle is violated. Disparate impact on a protected group always points to fairness, not transparency.</p>" },
  { id: "r8", deck: "Responsible AI", tag: "Privacy", front: "Differential privacy", back: "<p><strong>Differential privacy</strong> is a mathematical technique that adds carefully calibrated statistical noise to data or model outputs so that the model cannot reveal information about any individual training record.</p><p class=\"faint\">Exam trap: differential privacy is a privacy technique applied during training or data aggregation, not a security control like encryption. It addresses the risk of model memorization, not unauthorized data access.</p>" },
  { id: "r9", deck: "Responsible AI", tag: "Transparency", front: "Explainability and interpretability", back: "<p><strong>Explainability</strong> (or interpretability) means being able to understand why an AI model made a specific prediction, for example, which features most influenced the output. It supports the transparency and accountability principles.</p><p class=\"faint\">Exam trap: explainability is not the same as model simplicity. A complex deep learning model can be made more explainable with tools like SHAP values; a simple model is inherently more interpretable but may be less accurate.</p>" },
  { id: "r10", deck: "Responsible AI", tag: "Accountability", front: "Human-in-the-loop", back: "<p><strong>Human-in-the-loop</strong> is a design pattern where a human reviews, approves, or overrides AI decisions for high-stakes outcomes, ensuring accountability and catching model errors before they cause harm.</p><p class=\"faint\">Exam trap: human-in-the-loop does not mean humans do all the work; it means humans are inserted at key decision points. Full automation is appropriate for low-risk decisions; human review is required for high-stakes ones.</p>" },
  { id: "r11", deck: "Responsible AI", tag: "Fairness", front: "Model bias from training data", back: "<p><strong>Model bias</strong> from training data occurs when a model learns and perpetuates unfair patterns present in historical data, for example, a hiring model trained on historical decisions that systematically favored one gender.</p><p class=\"faint\">Exam trap: bias can enter a model from many sources (data collection, labeling, feature selection, feedback loops), not only from the algorithm itself. Fixing the algorithm without addressing the data does not eliminate bias.</p>" },
  { id: "r12", deck: "Responsible AI", tag: "Fairness", front: "Fairlearn", back: "<p><strong>Fairlearn</strong> is an open-source Python toolkit integrated with Azure Machine Learning that helps assess and mitigate fairness issues in machine learning models by analyzing disparity metrics across demographic groups.</p><p class=\"faint\">Exam trap: Fairlearn measures and helps reduce disparity in model outcomes; it does not guarantee that a model is perfectly fair, and it is one component of the responsible AI dashboard in Azure Machine Learning.</p>" },
  { id: "r13", deck: "Responsible AI", tag: "Accountability", front: "Responsible AI dashboard (Azure ML)", back: "<p>The <strong>responsible AI dashboard</strong> in Azure Machine Learning is an integrated tool that consolidates fairness, explainability, error analysis, causal analysis, and counterfactual insights to evaluate a model\u2019s responsible AI profile.</p><p class=\"faint\">Exam trap: the responsible AI dashboard is a post-training evaluation tool inside Azure Machine Learning; it is separate from Azure AI Content Safety, which is a runtime content filter for deployed AI applications.</p>" },
  { id: "r14", deck: "Responsible AI", tag: "Safety", front: "Content filters in Azure OpenAI", back: "<p><strong>Content filters</strong> in Azure OpenAI Service automatically detect and block harmful content categories (hate, violence, sexual, self-harm) in both prompts and completions at configurable severity thresholds.</p><p class=\"faint\">Exam trap: content filters apply at inference time to inputs and outputs; they are a runtime safety control, not a training-time technique. They are on by default and require approval to modify.</p>" },
  { id: "r15", deck: "Responsible AI", tag: "Safety", front: "Four-stage responsible generative AI process", back: "<p>Microsoft\u2019s responsible generative AI process has four stages: <strong>Identify</strong> potential harms, <strong>Measure</strong> the presence of those harms, <strong>Mitigate</strong> harms using layered controls, and <strong>Operate</strong> the solution responsibly with monitoring.</p><p class=\"faint\">Exam trap: the exam often tests the order of these stages. Mitigation comes after measurement, not before. You must measure harm before you can decide which mitigations to apply.</p>" },
  { id: "r16", deck: "Responsible AI", tag: "Transparency", front: "Microsoft responsible AI principles (count)", back: "<p>Microsoft defines <strong>six</strong> responsible AI principles: fairness, reliability and safety, privacy and security, inclusiveness, transparency, and accountability. Together they guide ethical AI development and deployment.</p><p class=\"faint\">Exam trap: the exam may ask how many principles there are or ask you to identify which principle applies to a scenario. Know all six names and their core meaning, especially fairness vs. inclusiveness vs. accountability.</p>" },
  { id: "c1", deck: "ML Concepts", tag: "Algorithms", front: "Regression", back: "<p><strong>Regression</strong> is a supervised machine learning task that predicts a continuous numerical output, such as house price, temperature, or sales revenue, given input features.</p><p class=\"faint\">Exam trap: regression predicts a number, not a category. If the output is a discrete label (spam/not-spam), that is classification, not regression.</p>" },
  { id: "c2", deck: "ML Concepts", tag: "Algorithms", front: "Classification", back: "<p><strong>Classification</strong> is a supervised machine learning task that predicts which discrete category an input belongs to, such as whether an email is spam or whether a tumor is malignant.</p><p class=\"faint\">Exam trap: classification outputs a class label (or probability per class), not a continuous number. Predicting \"will churn: yes or no\" is classification; predicting \"revenue next month\" is regression.</p>" },
  { id: "c3", deck: "ML Concepts", tag: "Algorithms", front: "Binary vs. multiclass classification", back: "<p><strong>Binary classification</strong> predicts one of exactly two classes (yes/no, spam/not-spam); <strong>multiclass classification</strong> predicts one of three or more mutually exclusive classes, such as categorizing news articles into sports, politics, or technology.</p><p class=\"faint\">Exam trap: multiclass assumes each input belongs to exactly one class. If an input can belong to multiple classes simultaneously (a movie that is both comedy and romance), that is multi-label classification.</p>" },
  { id: "c4", deck: "ML Concepts", tag: "Algorithms", front: "Clustering", back: "<p><strong>Clustering</strong> is an unsupervised machine learning task that groups similar data points together without predefined labels, discovering natural structure in data such as customer segments or document topics.</p><p class=\"faint\">Exam trap: clustering is unsupervised (no labels), while classification is supervised (labels required). If the scenario says \"we don\u2019t know the groups in advance,\" that points to clustering.</p>" },
  { id: "c5", deck: "ML Concepts", tag: "Learning Types", front: "Supervised vs. unsupervised learning", back: "<p><strong>Supervised learning</strong> trains on labeled data (input-output pairs); <strong>unsupervised learning</strong> trains on unlabeled data to discover patterns or structure. Regression and classification are supervised; clustering is unsupervised.</p><p class=\"faint\">Exam trap: reinforcement learning is a third type not covered in depth on AI-900, but know it exists. Semi-supervised learning uses a small amount of labeled data plus large amounts of unlabeled data.</p>" },
  { id: "c6", deck: "ML Concepts", tag: "Data", front: "Features", back: "<p><strong>Features</strong> are the input variables (columns) used by a model to make predictions. They represent the measurable properties of each data point, such as age, income, and number of purchases.</p><p class=\"faint\">Exam trap: features are inputs; labels are outputs. Feature engineering is the process of creating or transforming features to improve model performance.</p>" },
  { id: "c7", deck: "ML Concepts", tag: "Data", front: "Labels", back: "<p><strong>Labels</strong> are the target output values that a supervised model learns to predict, such as \"spam\" or \"not spam\" for email classification, or a house price for regression.</p><p class=\"faint\">Exam trap: labels exist only in supervised learning. In unsupervised learning (clustering), there are no labels; the model finds structure on its own.</p>" },
  { id: "c8", deck: "ML Concepts", tag: "Data", front: "Training dataset", back: "<p>The <strong>training dataset</strong> is the subset of data used to fit a machine learning model\u2014the model adjusts its parameters to minimize error on this data.</p><p class=\"faint\">Exam trap: evaluating a model\u2019s performance on its own training data is misleading because the model may have memorized it (overfitting). Use a separate validation or test set for unbiased evaluation.</p>" },
  { id: "c9", deck: "ML Concepts", tag: "Data", front: "Validation dataset", back: "<p>The <strong>validation dataset</strong> is a subset held out from training, used to tune hyperparameters and select the best model during development. It provides feedback during the iterative training process.</p><p class=\"faint\">Exam trap: the validation set guides model selection and tuning; the test set provides a final unbiased estimate of performance. Using the test set during tuning \"leaks\" information and overstates real-world performance.</p>" },
  { id: "c10", deck: "ML Concepts", tag: "Data", front: "Test dataset", back: "<p>The <strong>test dataset</strong> is a subset used only once, after all training and tuning are complete, to provide an unbiased final estimate of model performance on unseen data.</p><p class=\"faint\">Exam trap: the test set must never be used during training or hyperparameter tuning. Any use during development turns it into a validation set, and the performance estimate becomes optimistic.</p>" },
  { id: "c11", deck: "ML Concepts", tag: "Model Fit", front: "Overfitting", back: "<p><strong>Overfitting</strong> occurs when a model learns the training data too well, including its noise and random fluctuations, resulting in high accuracy on training data but poor generalization to new, unseen data.</p><p class=\"faint\">Exam trap: a large gap between training accuracy and validation accuracy is the key sign of overfitting. Remedies include more training data, regularization, or a simpler model (reducing complexity).</p>" },
  { id: "c12", deck: "ML Concepts", tag: "Model Fit", front: "Underfitting", back: "<p><strong>Underfitting</strong> occurs when a model is too simple to capture the underlying patterns in the training data, resulting in poor performance on both training and new data.</p><p class=\"faint\">Exam trap: if both training accuracy and validation accuracy are low, the model is underfitting. The remedy is a more complex model, more features, or more training\u2014the opposite of the overfitting remedy.</p>" },
  { id: "c13", deck: "ML Concepts", tag: "Deep Learning", front: "Deep learning", back: "<p><strong>Deep learning</strong> is a subset of machine learning that uses neural networks with many layers (deep architectures) to automatically learn hierarchical feature representations from raw data such as images or text.</p><p class=\"faint\">Exam trap: deep learning is a subset of machine learning, which is a subset of AI. It excels at unstructured data (images, audio, text) but typically requires large datasets and significant compute.</p>" },
  { id: "c14", deck: "ML Concepts", tag: "Deep Learning", front: "Neural network", back: "<p>A <strong>neural network</strong> is a machine learning model inspired by the brain, consisting of layers of interconnected nodes (neurons) with learnable weights. Each layer transforms its input before passing it to the next layer.</p><p class=\"faint\">Exam trap: a neural network with one hidden layer is \"shallow\"; a network with many hidden layers is \"deep\" (deep learning). Depth enables learning more abstract, complex patterns.</p>" },
  { id: "c15", deck: "ML Concepts", tag: "Deep Learning", front: "Transformer architecture", back: "<p>The <strong>Transformer</strong> is a neural network architecture based on self-attention mechanisms that processes all tokens in a sequence in parallel, enabling efficient training on large text (and other) datasets. It is the foundation of modern large language models.</p><p class=\"faint\">Exam trap: Transformers replaced recurrent neural networks (RNNs) as the dominant architecture for NLP because they parallelize better and capture long-range dependencies more effectively.</p>" },
  { id: "c16", deck: "ML Concepts", tag: "Deep Learning", front: "Attention mechanism", back: "<p>The <strong>attention mechanism</strong> allows a model to focus on the most relevant parts of an input sequence when producing each output token, capturing relationships between words regardless of their distance in the sequence.</p><p class=\"faint\">Exam trap: \"self-attention\" in a Transformer means the model attends to other positions in the same sequence, not to an external memory. This is the key innovation that makes Transformers powerful.</p>" },
  { id: "c17", deck: "ML Concepts", tag: "Metrics", front: "Confusion matrix", back: "<p>A <strong>confusion matrix</strong> is a table that summarizes classification model performance by showing counts of true positives, true negatives, false positives, and false negatives across all classes.</p><p class=\"faint\">Exam trap: a confusion matrix applies to classification tasks only, not regression. For binary classification it is 2x2; for multiclass it is NxN where N is the number of classes.</p>" },
  { id: "c18", deck: "ML Concepts", tag: "Metrics", front: "True positive / false positive / true negative / false negative", back: "<p>A <strong>true positive (TP)</strong> is a correctly predicted positive; a <strong>false positive (FP)</strong> is an incorrect positive prediction (type I error); a <strong>true negative (TN)</strong> is a correctly predicted negative; a <strong>false negative (FN)</strong> is a missed positive (type II error).</p><p class=\"faint\">Exam trap: a false positive is also called a \"type I error\" and a false negative a \"type II error.\" In a medical test, a false negative (missed disease) is usually more dangerous than a false positive.</p>" },
  { id: "c19", deck: "ML Concepts", tag: "Metrics", front: "Accuracy", back: "<p><strong>Accuracy</strong> is the proportion of all predictions that are correct: (TP + TN) / (TP + TN + FP + FN). It measures overall correctness across all classes.</p><p class=\"faint\">Exam trap: accuracy is misleading for imbalanced datasets. If 95% of samples are negative, a model that always predicts negative achieves 95% accuracy yet is useless. Use precision, recall, or F1 instead.</p>" },
  { id: "c20", deck: "ML Concepts", tag: "Metrics", front: "Precision", back: "<p><strong>Precision</strong> is the proportion of positive predictions that are actually correct: TP / (TP + FP). High precision means few false alarms (false positives).</p><p class=\"faint\">Exam trap: optimize for precision when false positives are costly, such as a spam filter that should not block legitimate email. When false negatives are costly (cancer detection), optimize for recall instead.</p>" },
  { id: "c21", deck: "ML Concepts", tag: "Metrics", front: "Recall", back: "<p><strong>Recall</strong> (also called sensitivity or true positive rate) is the proportion of actual positives that the model correctly identifies: TP / (TP + FN). High recall means few missed positives.</p><p class=\"faint\">Exam trap: recall is critical when missing a positive is dangerous, such as failing to detect a disease or a security threat. There is typically a precision-recall tradeoff: increasing one often decreases the other.</p>" },
  { id: "c22", deck: "ML Concepts", tag: "Metrics", front: "F1 score", back: "<p>The <strong>F1 score</strong> is the harmonic mean of precision and recall: 2 * (precision * recall) / (precision + recall). It balances both metrics and is useful when classes are imbalanced.</p><p class=\"faint\">Exam trap: F1 is not simply the average of precision and recall; it is the harmonic mean, which penalizes large disparities between the two. Use F1 when both false positives and false negatives matter equally.</p>" },
  { id: "c23", deck: "ML Concepts", tag: "Metrics", front: "AUC and ROC curve", back: "<p>The <strong>ROC (receiver operating characteristic) curve</strong> plots the true positive rate against the false positive rate at every classification threshold. The <strong>AUC (area under the curve)</strong> summarizes this as a single number; a perfect model has AUC = 1.0, and random guessing gives AUC = 0.5.</p><p class=\"faint\">Exam trap: AUC is threshold-independent and works well for imbalanced datasets. Do not confuse AUC-ROC with AUC-PR (area under the precision-recall curve), which is preferred when positives are very rare.</p>" },
  { id: "c24", deck: "ML Concepts", tag: "Metrics", front: "R-squared (R2)", back: "<p><strong>R-squared (R2)</strong> measures the proportion of variance in the target variable explained by a regression model. R2 = 1 means perfect fit; R2 = 0 means the model explains no variance better than predicting the mean.</p><p class=\"faint\">Exam trap: R2 can be negative if the model performs worse than a naive mean-predicting baseline. A high R2 does not guarantee good predictions on new data if the model is overfitting.</p>" },
  { id: "c25", deck: "ML Concepts", tag: "Metrics", front: "RMSE (root mean squared error)", back: "<p><strong>RMSE</strong> is a regression metric calculated as the square root of the average squared differences between predicted and actual values. It penalizes large errors more heavily than small ones due to the squaring.</p><p class=\"faint\">Exam trap: RMSE is in the same units as the target variable, making it interpretable. It is more sensitive to outliers than MAE. Lower RMSE is better.</p>" },
  { id: "c26", deck: "ML Concepts", tag: "Metrics", front: "MAE and choosing a metric for imbalanced data", back: "<p><strong>MAE (mean absolute error)</strong> is the average of the absolute differences between predicted and actual values. For imbalanced classification datasets, accuracy is misleading; use <strong>F1 score, AUC, or precision/recall</strong> instead to get a true picture of performance.</p><p class=\"faint\">Exam trap: if the exam describes a scenario with rare positive events (fraud, disease), the correct metric choice is F1, AUC, or recall\u2014not accuracy. Accuracy rewards always predicting the majority class.</p>" },
  { id: "m1", deck: "Azure Machine Learning", tag: "Studio", front: "Azure Machine Learning studio", back: "<p><strong>Azure Machine Learning studio</strong> is the web-based portal for the Azure Machine Learning service where data scientists and ML engineers author, train, deploy, and monitor machine learning models using a unified UI.</p><p class=\"faint\">Exam trap: Azure Machine Learning studio is specific to Azure ML. Do not confuse it with Azure AI Foundry portal, which is used for generative AI and Azure AI Services development.</p>" },
  { id: "m2", deck: "Azure Machine Learning", tag: "AutoML", front: "Automated machine learning (AutoML)", back: "<p><strong>Automated machine learning (AutoML)</strong> in Azure Machine Learning automatically tries multiple algorithms and hyperparameter combinations to find the best model for a given dataset and task type, requiring minimal ML expertise.</p><p class=\"faint\">Exam trap: AutoML selects the algorithm for you; the designer lets you build a pipeline visually with explicit algorithm choices. AutoML is faster to start but gives less control than the designer or code.</p>" },
  { id: "m3", deck: "Azure Machine Learning", tag: "Studio", front: "Azure ML designer", back: "<p>The <strong>Azure ML designer</strong> is a drag-and-drop visual interface in Azure Machine Learning studio that lets you build machine learning pipelines by connecting pre-built modules for data preparation, training, and evaluation.</p><p class=\"faint\">Exam trap: the designer requires you to select and configure each step manually; AutoML selects the algorithm automatically. Use the designer when you want visual control but not full code authoring.</p>" },
  { id: "m4", deck: "Azure Machine Learning", tag: "Compute", front: "Compute instance", back: "<p>A <strong>compute instance</strong> in Azure Machine Learning is a managed cloud-hosted workstation (virtual machine) used by a single data scientist for interactive development, notebook authoring, and experimentation.</p><p class=\"faint\">Exam trap: a compute instance is for development (one user, always-on optional); a compute cluster is for scaled training jobs (multi-node, scales to zero). Use the right one for the right purpose.</p>" },
  { id: "m5", deck: "Azure Machine Learning", tag: "Compute", front: "Compute cluster", back: "<p>A <strong>compute cluster</strong> in Azure Machine Learning is a managed multi-node cluster that scales up during training jobs and scales down to zero when idle, optimizing cost for batch training workloads.</p><p class=\"faint\">Exam trap: compute clusters are used for training jobs (AutoML, pipelines); inference clusters (backed by AKS) are used for real-time scoring endpoints. Do not use a compute cluster for real-time inference.</p>" },
  { id: "m6", deck: "Azure Machine Learning", tag: "Compute", front: "Inference cluster", back: "<p>An <strong>inference cluster</strong> in Azure Machine Learning is an Azure Kubernetes Service (AKS) cluster attached to the workspace to host real-time model endpoints for production-scale, low-latency predictions.</p><p class=\"faint\">Exam trap: inference clusters are for real-time endpoints requiring high throughput and low latency. Batch endpoints run on compute clusters. Managed online endpoints abstract the AKS cluster management.</p>" },
  { id: "m7", deck: "Azure Machine Learning", tag: "Data", front: "Datastore", back: "<p>A <strong>datastore</strong> in Azure Machine Learning is a registered connection to a storage service (Azure Blob Storage, Azure Data Lake, etc.) that stores credentials securely so training jobs can read data without embedding connection strings in code.</p><p class=\"faint\">Exam trap: a datastore is a connection to storage, not the data itself. A data asset (dataset) is a versioned reference to specific data files or folders within a datastore.</p>" },
  { id: "m8", deck: "Azure Machine Learning", tag: "Data", front: "Data asset", back: "<p>A <strong>data asset</strong> (formerly called a dataset) in Azure Machine Learning is a versioned, named reference to data stored in a datastore or public URL, enabling reproducible training jobs and data lineage tracking.</p><p class=\"faint\">Exam trap: a data asset is a pointer with version metadata, not a copy of the data. If the underlying storage changes without creating a new version, the data asset may no longer reflect what was used in a prior experiment.</p>" },
  { id: "m9", deck: "Azure Machine Learning", tag: "Models", front: "Model registry", back: "<p>The <strong>model registry</strong> in Azure Machine Learning is a centralized store for versioned trained models, including metadata such as metrics, training run lineage, and tags, enabling tracking and deployment governance.</p><p class=\"faint\">Exam trap: registering a model does not deploy it; deployment is a separate step. The registry is a catalog where models are stored and versioned before being promoted to a deployment endpoint.</p>" },
  { id: "m10", deck: "Azure Machine Learning", tag: "Endpoints", front: "Real-time endpoint", back: "<p>A <strong>real-time endpoint</strong> in Azure Machine Learning is a deployed web service that returns predictions synchronously in milliseconds for individual or small-batch requests, backed by managed online endpoints or AKS.</p><p class=\"faint\">Exam trap: real-time endpoints are for interactive, low-latency use cases. If predictions are needed for millions of records overnight, use a batch endpoint, which is more cost-efficient for large volumes.</p>" },
  { id: "m11", deck: "Azure Machine Learning", tag: "Endpoints", front: "Batch endpoint", back: "<p>A <strong>batch endpoint</strong> in Azure Machine Learning runs a scoring pipeline asynchronously on large datasets, writing predictions to storage rather than returning them immediately, and is optimized for throughput over latency.</p><p class=\"faint\">Exam trap: batch endpoints are asynchronous and not suitable for user-facing real-time scenarios. If a scenario describes \"scoring a new customer request immediately,\" choose a real-time endpoint.</p>" },
  { id: "m12", deck: "Azure Machine Learning", tag: "Pipelines", front: "Azure ML pipeline", back: "<p>An <strong>Azure ML pipeline</strong> is a reusable, multi-step workflow that chains data preparation, training, evaluation, and registration steps, enabling automation and reproducibility of the end-to-end ML lifecycle.</p><p class=\"faint\">Exam trap: an Azure ML pipeline is for ML workflow orchestration; it is not the same as Azure Pipelines (a CI/CD product in Azure DevOps), though both may be used together in MLOps workflows.</p>" },
  { id: "m13", deck: "Azure Machine Learning", tag: "Jobs", front: "Job (Azure ML)", back: "<p>A <strong>job</strong> in Azure Machine Learning is a single execution unit\u2014a training run, AutoML experiment, or pipeline step\u2014that records inputs, outputs, parameters, metrics, and logs for reproducibility and comparison.</p><p class=\"faint\">Exam trap: jobs are tracked automatically in Azure ML experiments. Each job run gets a unique ID, and you can compare metrics across runs to select the best model.</p>" },
  { id: "m14", deck: "Azure Machine Learning", tag: "Environments", front: "Environment (Azure ML)", back: "<p>An <strong>environment</strong> in Azure Machine Learning specifies the software dependencies (Python packages, Docker base image, conda settings) needed to run a training or inference job, enabling reproducibility across compute targets.</p><p class=\"faint\">Exam trap: environments in Azure ML are versioned just like models and data assets. Curated environments are Microsoft-provided, prebuilt environments; custom environments are defined by the user.</p>" },
  { id: "m15", deck: "Azure Machine Learning", tag: "MLOps", front: "MLflow", back: "<p><strong>MLflow</strong> is an open-source MLOps platform integrated with Azure Machine Learning that provides experiment tracking, model logging, model registry, and deployment capabilities through a standard API.</p><p class=\"faint\">Exam trap: Azure ML uses MLflow natively, meaning models logged with MLflow\u2019s API are automatically tracked in Azure ML experiments. MLflow is not Azure-only; it also works with Databricks and other platforms.</p>" },
  { id: "m16", deck: "Azure Machine Learning", tag: "Responsible AI", front: "Responsible AI dashboard (in Azure ML)", back: "<p>The <strong>responsible AI dashboard</strong> in Azure Machine Learning aggregates fairness analysis (Fairlearn), explainability (SHAP), error analysis, and causal insights into one interface for evaluating models against responsible AI principles.</p><p class=\"faint\">Exam trap: the responsible AI dashboard requires generating a responsible AI insights component during an Azure ML job. It is not automatically available for all models; you must configure it explicitly.</p>" },
  { id: "m17", deck: "Azure Machine Learning", tag: "Features", front: "Feature engineering and featurization", back: "<p><strong>Feature engineering</strong> is the process of creating, transforming, or selecting input features to improve model performance. <strong>Featurization</strong> in AutoML refers to the automatic preprocessing steps (normalization, encoding, imputation) that AutoML applies before training.</p><p class=\"faint\">Exam trap: AutoML featurization is automatic but can be customized or turned off. Manual feature engineering in notebooks or the designer gives more control but requires more expertise.</p>" },
  { id: "m18", deck: "Azure Machine Learning", tag: "Tuning", front: "Hyperparameter tuning", back: "<p><strong>Hyperparameter tuning</strong> (also called hyperparameter optimization or sweep jobs in Azure ML) is the process of searching for the best model configuration values (learning rate, depth, regularization) that are set before training, not learned from data.</p><p class=\"faint\">Exam trap: hyperparameters are different from model parameters (weights). Weights are learned during training; hyperparameters are set by the practitioner and tuned using search strategies like random search or Bayesian optimization.</p>" },
  { id: "m19", deck: "Azure Machine Learning", tag: "Studio", front: "Notebooks in Azure ML", back: "<p><strong>Notebooks</strong> in Azure Machine Learning studio are Jupyter-compatible notebooks that run on a compute instance, enabling interactive Python development, data exploration, and full-code ML experimentation within the Azure ML workspace.</p><p class=\"faint\">Exam trap: notebooks give maximum flexibility and require coding skills. For users who prefer no-code, use AutoML; for low-code drag-and-drop, use the designer. Notebooks are the \"code-first\" option.</p>" },
  { id: "m20", deck: "Azure Machine Learning", tag: "AutoML", front: "AutoML vs. designer vs. code", back: "<p>Choose <strong>AutoML</strong> when you want the fastest path to a model with minimal ML expertise; choose the <strong>designer</strong> for visual, low-code pipeline authoring with explicit algorithm control; choose <strong>code (notebooks/scripts)</strong> for maximum flexibility and custom architectures.</p><p class=\"faint\">Exam trap: AutoML can be invoked via the studio UI or via the Python SDK. The designer and AutoML both produce pipelines but differ in who selects the algorithm. Code is always available in parallel with both tools.</p>" },
  { id: "v1", deck: "Computer Vision", tag: "Classification", front: "Image classification", back: "<p><strong>Image classification</strong> assigns a single label to an entire image, answering the question \"what is in this image?\" For example, classifying a photo as \"cat\" or \"dog.\"</p><p class=\"faint\">Exam trap: image classification labels the whole image; object detection labels individual objects and returns their locations. If the scenario requires finding where in an image an object is, that is detection, not classification.</p>" },
  { id: "v2", deck: "Computer Vision", tag: "Detection", front: "Object detection", back: "<p><strong>Object detection</strong> identifies and locates multiple objects within an image, returning a class label and a bounding box for each detected object. It answers \"what objects are here, and where are they?\"</p><p class=\"faint\">Exam trap: object detection is more complex than classification. If a scenario says \"identify whether an image contains a car\" (yes/no), classification suffices. If it says \"find all cars and their positions,\" use object detection.</p>" },
  { id: "v3", deck: "Computer Vision", tag: "Detection", front: "Bounding box", back: "<p>A <strong>bounding box</strong> is the rectangular region (defined by x, y, width, height or top-left and bottom-right coordinates) that encloses a detected object in an image, returned as part of an object detection result.</p><p class=\"faint\">Exam trap: bounding boxes are axis-aligned rectangles. They are approximate containers; they do not follow the exact outline of an object. Pixel-level outlines are produced by segmentation models.</p>" },
  { id: "v4", deck: "Computer Vision", tag: "Segmentation", front: "Semantic segmentation", back: "<p><strong>Semantic segmentation</strong> assigns a class label to every individual pixel in an image, enabling precise delineation of objects such as road, sky, and pedestrians in an autonomous driving scene.</p><p class=\"faint\">Exam trap: semantic segmentation labels pixels by class but does not distinguish between separate instances of the same class. Instance segmentation (a separate task) distinguishes individual objects of the same class.</p>" },
  { id: "v5", deck: "Computer Vision", tag: "OCR", front: "Optical character recognition (OCR)", back: "<p><strong>Optical character recognition (OCR)</strong> detects and extracts printed or handwritten text from images and documents, converting it into machine-readable text strings.</p><p class=\"faint\">Exam trap: OCR extracts raw text (characters and words); document intelligence (Form Recognizer) goes further by understanding the semantic structure of the document, such as which text is a field name vs. a value.</p>" },
  { id: "v6", deck: "Computer Vision", tag: "OCR", front: "Read capability (Azure AI Vision)", back: "<p>The <strong>Read</strong> capability of Azure AI Vision is an OCR API optimized for extracting dense text from documents and images at scale, handling printed and handwritten text in multiple languages and returning bounding boxes for each word.</p><p class=\"faint\">Exam trap: the Read API is for text-heavy documents and is more powerful than the older Azure AI Vision OCR endpoint. For structured document field extraction (invoices, receipts), use Azure AI Document Intelligence instead.</p>" },
  { id: "v7", deck: "Computer Vision", tag: "Face", front: "Face detection", back: "<p><strong>Face detection</strong> locates human faces in an image and returns bounding boxes and basic attributes (number of faces, position), without identifying who the faces belong to.</p><p class=\"faint\">Exam trap: face detection finds faces; face recognition identifies who those faces belong to by comparing against a known gallery. Detection is a prerequisite for recognition but does not require identity data.</p>" },
  { id: "v8", deck: "Computer Vision", tag: "Face", front: "Face analysis", back: "<p><strong>Face analysis</strong> extends face detection to return attributes about each detected face, such as estimated age, emotion, glasses, and head pose, without requiring identification of the individual.</p><p class=\"faint\">Exam trap: face analysis attributes such as emotion or age are estimates with uncertainty. Azure AI Face\u2019s attribute predictions (e.g., emotion) are not always accurate and should not be used for consequential decisions.</p>" },
  { id: "v9", deck: "Computer Vision", tag: "Face", front: "Face recognition", back: "<p><strong>Face recognition</strong> identifies a detected face by comparing it against a gallery of known individuals, returning the identity of the matched person. It requires a pre-enrolled set of reference images.</p><p class=\"faint\">Exam trap: face recognition is subject to Azure AI Face\u2019s Limited Access policy and requires approval to use. It is distinct from face verification, which checks if two specific face images are of the same person.</p>" },
  { id: "v10", deck: "Computer Vision", tag: "Face", front: "Face verification", back: "<p><strong>Face verification</strong> determines whether two face images belong to the same person, returning a confidence score. It is a 1-to-1 comparison, not a 1-to-many search against a gallery.</p><p class=\"faint\">Exam trap: face verification is 1:1 (\"is this the same person as that reference photo?\"); face identification is 1:N (\"who is this person among these known individuals?\"). Both are covered by the Limited Access policy.</p>" },
  { id: "v11", deck: "Computer Vision", tag: "Face", front: "Face Limited Access policy", back: "<p>The <strong>Face Limited Access policy</strong> requires customers to apply for and receive approval from Microsoft before using Azure AI Face capabilities that identify or verify individuals, due to the higher privacy and ethical risks of facial recognition.</p><p class=\"faint\">Exam trap: general face detection and face attribute analysis do not require Limited Access approval. Only identification, verification, and celebrity recognition features are gated. This is an example of responsible AI in practice.</p>" },
  { id: "v12", deck: "Computer Vision", tag: "Vision", front: "Azure AI Vision image analysis", back: "<p><strong>Azure AI Vision image analysis</strong> is a cloud API that analyzes images to return captions, tags, objects, people, brands, color schemes, and smart crop coordinates using Microsoft-pretrained models.</p><p class=\"faint\">Exam trap: Azure AI Vision uses pre-trained Microsoft models; you cannot train it on your own object categories. For custom categories, use Azure AI Custom Vision instead.</p>" },
  { id: "v13", deck: "Computer Vision", tag: "Vision", front: "Captions and dense captions", back: "<p>The <strong>caption</strong> feature of Azure AI Vision returns a single natural-language description of an entire image; <strong>dense captions</strong> returns individual captions for the main image plus each detected region of interest within it.</p><p class=\"faint\">Exam trap: captions describe the overall scene in plain language; tags return a list of keywords. Both come from Azure AI Vision\u2019s image analysis API but serve different purposes.</p>" },
  { id: "v14", deck: "Computer Vision", tag: "Vision", front: "Tags in Azure AI Vision", back: "<p><strong>Tags</strong> in Azure AI Vision are a list of keyword labels associated with the objects, concepts, and settings detected in an image, each with a confidence score, useful for cataloging and searching images.</p><p class=\"faint\">Exam trap: tags are flat keywords (e.g., \"cat,\" \"outdoor,\" \"grass\"); they do not include location. Object detection returns both a label and a bounding box. Choose tags for keyword-only indexing, detection for locating objects.</p>" },
  { id: "v15", deck: "Computer Vision", tag: "Vision", front: "Smart crop and background removal", back: "<p><strong>Smart crop</strong> in Azure AI Vision automatically identifies the best region of an image to crop for a given aspect ratio, focusing on the primary subject. <strong>Background removal</strong> separates the foreground subject from the background.</p><p class=\"faint\">Exam trap: smart crop and background removal are features of Azure AI Vision\u2019s image analysis API, not Azure AI Custom Vision. Custom Vision is for training models on your own labeled data.</p>" },
  { id: "v16", deck: "Computer Vision", tag: "Custom Vision", front: "Azure AI Custom Vision", back: "<p><strong>Azure AI Custom Vision</strong> is a service that lets you train and deploy image classification and object detection models on your own labeled image data without writing ML code, using a simple portal or REST API.</p><p class=\"faint\">Exam trap: Custom Vision requires your own labeled training data (images + labels). Azure AI Vision (the general analysis service) uses Microsoft pretrained models and does not need your data.</p>" },
  { id: "v17", deck: "Computer Vision", tag: "Custom Vision", front: "Custom classification vs. custom object detection", back: "<p>In Azure AI Custom Vision, <strong>custom classification</strong> assigns one or more labels to an entire image; <strong>custom object detection</strong> draws bounding boxes around specific objects and labels each one within an image.</p><p class=\"faint\">Exam trap: choose custom object detection when you need to locate objects in an image, not just label the image as a whole. Object detection labeling is more time-consuming because you must draw bounding boxes on training images.</p>" },
  { id: "v18", deck: "Computer Vision", tag: "Custom Vision", front: "Training resource vs. prediction resource", back: "<p>In Azure AI Custom Vision, the <strong>training resource</strong> is used to upload images, label them, and train models; the <strong>prediction resource</strong> is a separate endpoint used by applications to call the trained model for inference.</p><p class=\"faint\">Exam trap: you need both resources to build and consume a Custom Vision model. The training endpoint is not exposed to end-user applications; only the prediction endpoint is used in production.</p>" },
  { id: "v19", deck: "Computer Vision", tag: "Document", front: "Azure AI Document Intelligence prebuilt models", back: "<p><strong>Azure AI Document Intelligence prebuilt models</strong> extract structured data from specific document types (invoices, receipts, ID documents, tax forms) without requiring custom training, using Microsoft-trained models.</p><p class=\"faint\">Exam trap: prebuilt models work well for common document types. For a proprietary form with unusual fields, you need to train a custom document model using labeled examples of your own documents.</p>" },
  { id: "v20", deck: "Computer Vision", tag: "Document", front: "Custom document models", back: "<p><strong>Custom document models</strong> in Azure AI Document Intelligence are trained on your own labeled document examples to extract specific fields from proprietary form layouts that prebuilt models do not cover.</p><p class=\"faint\">Exam trap: custom models require labeled training documents (field labels applied to sample PDFs or images). The more varied your document layouts, the more training examples you need for reliable extraction.</p>" },
  { id: "v21", deck: "Computer Vision", tag: "Video", front: "Azure AI Video Indexer", back: "<p><strong>Azure AI Video Indexer</strong> is a cloud service that extracts rich metadata from video, including transcription, speaker identification, face detection, OCR from frames, keyframe extraction, sentiment, and topic detection.</p><p class=\"faint\">Exam trap: Azure AI Video Indexer is specifically for video analysis at scale. Do not confuse it with Azure AI Vision\u2019s spatial analysis feature, which processes live video streams for real-time people-counting and distance analysis.</p>" },
  { id: "v22", deck: "Computer Vision", tag: "Spatial", front: "Spatial analysis", back: "<p><strong>Spatial analysis</strong> in Azure AI Vision processes live or recorded video from cameras to detect people, count occupancy, analyze movement patterns, and enforce social distancing in physical spaces.</p><p class=\"faint\">Exam trap: spatial analysis runs on-premises on an IoT edge device (Azure Stack Edge or NVIDIA GPU hardware) and requires the Azure AI Vision container. It is not a pure cloud API like image analysis.</p>" },
  { id: "v23", deck: "Computer Vision", tag: "Vision", front: "Azure AI Vision vs. Azure AI Custom Vision", back: "<p><strong>Azure AI Vision</strong> uses Microsoft pretrained models to analyze any image for general features (tags, captions, OCR, faces) without custom training. <strong>Azure AI Custom Vision</strong> trains models on your own labeled data for domain-specific classification or detection tasks.</p><p class=\"faint\">Exam trap: if the scenario involves standard image content (scenes, objects, text), use Azure AI Vision. If it involves specialized categories (company product SKUs, custom defect types), use Custom Vision with your own labeled images.</p>" },
  { id: "v24", deck: "Computer Vision", tag: "OCR", front: "OCR vs. document intelligence", back: "<p><strong>OCR</strong> extracts raw text characters and their positions from images; <strong>Azure AI Document Intelligence</strong> goes further by extracting structured key-value pairs, tables, and form fields with semantic understanding of document layout.</p><p class=\"faint\">Exam trap: use OCR (Azure AI Vision Read API) when you need to read text from unstructured images (photos, signs). Use Document Intelligence when you need to pull specific fields (invoice number, total amount) from business documents.</p>" },
  { id: "n1", deck: "NLP \u0026 Speech", tag: "NLP", front: "Key phrase extraction", back: "<p><strong>Key phrase extraction</strong> is an NLP capability that identifies the most important words and phrases in a text document, summarizing its main topics without full sentence analysis.</p><p class=\"faint\">Exam trap: key phrase extraction returns keywords, not sentiment. If the scenario asks \"what is the document about?\" use key phrase extraction. If it asks \"is the document positive or negative?\" use sentiment analysis.</p>" },
  { id: "n2", deck: "NLP \u0026 Speech", tag: "NLP", front: "Named entity recognition (NER)", back: "<p><strong>Named entity recognition (NER)</strong> identifies and classifies named real-world entities in text into categories such as person, organization, location, date, and quantity.</p><p class=\"faint\">Exam trap: NER identifies entities by category but does not extract key-value pairs from forms. Do not confuse NER with key phrase extraction, which returns important phrases regardless of whether they are named entities.</p>" },
  { id: "n3", deck: "NLP \u0026 Speech", tag: "NLP", front: "PII detection", back: "<p><strong>PII (personally identifiable information) detection</strong> in Azure AI Language identifies and can redact sensitive personal information in text, such as names, phone numbers, SSNs, credit card numbers, and email addresses.</p><p class=\"faint\">Exam trap: PII detection is a specialized form of NER focused on sensitive personal data. The service can either identify PII entities or automatically redact them by replacing them with placeholders.</p>" },
  { id: "n4", deck: "NLP \u0026 Speech", tag: "NLP", front: "Sentiment analysis", back: "<p><strong>Sentiment analysis</strong> classifies the overall emotional tone of a text document as positive, negative, neutral, or mixed, and may return a confidence score for each category.</p><p class=\"faint\">Exam trap: sentiment analysis gives an overall tone; opinion mining (aspect-based sentiment) goes further by linking sentiment to specific aspects mentioned in the text (e.g., \"the battery is bad\" \u2014 negative about the battery).</p>" },
  { id: "n5", deck: "NLP \u0026 Speech", tag: "NLP", front: "Opinion mining (aspect-based sentiment)", back: "<p><strong>Opinion mining</strong> (also called aspect-based sentiment analysis) identifies sentiments linked to specific entities or aspects within text, such as determining that a product review is positive about speed but negative about price.</p><p class=\"faint\">Exam trap: opinion mining is a feature within Azure AI Language\u2019s sentiment analysis capability. It is more granular than overall sentiment. Enable it by setting the optional opinion mining parameter on the sentiment analysis call.</p>" },
  { id: "n6", deck: "NLP \u0026 Speech", tag: "NLP", front: "Language detection", back: "<p><strong>Language detection</strong> identifies the written language of a text document and returns the language name and ISO 639-1 code (e.g., \"English\", \"en\") along with a confidence score.</p><p class=\"faint\">Exam trap: language detection identifies the script language (French, Japanese, etc.) but does not translate. Translation is a separate service (Azure AI Translator). Language detection is often the first step in a multilingual text pipeline.</p>" },
  { id: "n7", deck: "NLP \u0026 Speech", tag: "NLP", front: "Extractive summarization", back: "<p><strong>Extractive summarization</strong> produces a summary by selecting and returning the most important sentences verbatim from the original document without generating any new text.</p><p class=\"faint\">Exam trap: extractive summarization reuses sentences from the source; abstractive summarization generates new sentences. Extractive is more faithful to the original text; abstractive may be more fluent but can introduce errors.</p>" },
  { id: "n8", deck: "NLP \u0026 Speech", tag: "NLP", front: "Abstractive summarization", back: "<p><strong>Abstractive summarization</strong> generates a concise summary in new words that captures the key information from a document, potentially combining and rephrasing content rather than copying sentences directly.</p><p class=\"faint\">Exam trap: abstractive summaries are generated text and may hallucinate or subtly misrepresent the source. For highly accurate, verifiable summaries of sensitive documents, extractive summarization is safer.</p>" },
  { id: "n9", deck: "NLP \u0026 Speech", tag: "NLP", front: "Question answering", back: "<p><strong>Question answering</strong> in Azure AI Language matches a user\u2019s question to the best answer from a knowledge base of question-and-answer pairs, returning a confidence score with the answer.</p><p class=\"faint\">Exam trap: question answering retrieves pre-authored answers from a knowledge base; it does not generate answers dynamically. For generative answers from unstructured documents, combine question answering with RAG or use Azure OpenAI.</p>" },
  { id: "n10", deck: "NLP \u0026 Speech", tag: "NLP", front: "Custom question answering", back: "<p><strong>Custom question answering</strong> is a feature of Azure AI Language that lets you build and train a question-and-answer knowledge base from your own documents, URLs, or manually authored QA pairs for deployment as a bot or app.</p><p class=\"faint\">Exam trap: custom question answering replaced the standalone QnA Maker service. The knowledge base needs to be published before it can be queried. It works on top of Azure AI Search for indexing.</p>" },
  { id: "n11", deck: "NLP \u0026 Speech", tag: "NLP", front: "Conversational language understanding (CLU)", back: "<p><strong>Conversational language understanding (CLU)</strong> is the Azure AI Language feature that enables apps to understand natural-language commands by extracting intents (what the user wants) and entities (key details) from utterances.</p><p class=\"faint\">Exam trap: CLU replaced the standalone LUIS (Language Understanding) service. CLU is used for building bots and apps that interpret user commands; it is not the same as Azure OpenAI chat completions.</p>" },
  { id: "n12", deck: "NLP \u0026 Speech", tag: "NLP", front: "Utterance, intent, entity", back: "<p>In conversational language understanding, an <strong>utterance</strong> is the user\u2019s input text; an <strong>intent</strong> is the user\u2019s goal inferred from that text (e.g., BookFlight); an <strong>entity</strong> is a specific piece of information extracted from the utterance (e.g., destination city).</p><p class=\"faint\">Exam trap: one utterance can have one intent but multiple entities. For example, \"Book a flight to Paris on Friday\" has intent=BookFlight, entity:destination=Paris, entity:date=Friday.</p>" },
  { id: "n13", deck: "NLP \u0026 Speech", tag: "NLP", front: "Text analytics for health", back: "<p><strong>Text analytics for health</strong> in Azure AI Language extracts and links medical information from unstructured clinical text, identifying entities such as diagnoses, medications, symptoms, and dosages and relating them to standard ontologies.</p><p class=\"faint\">Exam trap: text analytics for health is designed for clinical notes and medical records, not general sentiment or entity recognition. It is not a substitute for professional medical advice or a certified medical device.</p>" },
  { id: "n14", deck: "NLP \u0026 Speech", tag: "NLP", front: "Custom text classification", back: "<p><strong>Custom text classification</strong> in Azure AI Language trains a model to assign one or more custom labels to text documents based on your own categories and labeled training examples, beyond the built-in categories.</p><p class=\"faint\">Exam trap: custom text classification requires labeled training data. For predefined categories (sentiment, language), use built-in Azure AI Language features. Custom classification is for domain-specific taxonomies you define.</p>" },
  { id: "n15", deck: "NLP \u0026 Speech", tag: "Speech", front: "Speech to text", back: "<p><strong>Speech to text</strong> (also called automatic speech recognition, ASR) converts spoken audio into a text transcript. Azure AI Speech provides real-time and batch transcription with language and domain customization.</p><p class=\"faint\">Exam trap: speech to text produces a transcript; the transcript can then be analyzed with NLP features (sentiment, NER, etc.) as a second step. The two are separate capabilities that can be combined in a pipeline.</p>" },
  { id: "n16", deck: "NLP \u0026 Speech", tag: "Speech", front: "Text to speech", back: "<p><strong>Text to speech</strong> (TTS) synthesizes natural-sounding spoken audio from text input. Azure AI Speech provides prebuilt neural voices and supports SSML for controlling pronunciation, rate, and emphasis.</p><p class=\"faint\">Exam trap: text to speech is the reverse of speech to text; it generates audio from text. Do not confuse neural voice (a realistic synthesized voice) with custom neural voice (a voice trained to sound like a specific person).</p>" },
  { id: "n17", deck: "NLP \u0026 Speech", tag: "Speech", front: "Neural voice", back: "<p>A <strong>neural voice</strong> in Azure AI Speech is a prebuilt, AI-generated voice that sounds natural and human-like, produced by deep neural network models trained on high-quality voice recordings.</p><p class=\"faint\">Exam trap: neural voices are Microsoft\u2019s prebuilt voices. Custom neural voice lets you train a model to mimic a specific person\u2019s voice and requires consent documentation and Microsoft approval.</p>" },
  { id: "n18", deck: "NLP \u0026 Speech", tag: "Speech", front: "Custom neural voice", back: "<p><strong>Custom neural voice</strong> creates a unique synthetic voice model that replicates a specific speaker\u2019s voice by training on recordings of that speaker. It is subject to the Limited Access policy due to potential misuse (deepfakes).</p><p class=\"faint\">Exam trap: custom neural voice requires speaker consent and is subject to Microsoft\u2019s Limited Access policy. It is not simply selecting from a library of voices; it involves training a voice on a specific person\u2019s recordings.</p>" },
  { id: "n19", deck: "NLP \u0026 Speech", tag: "Speech", front: "SSML (Speech Synthesis Markup Language)", back: "<p><strong>SSML</strong> is an XML-based markup language for controlling text-to-speech output, allowing control over pronunciation, speaking rate, pitch, pauses, and emphasis to produce more natural-sounding audio.</p><p class=\"faint\">Exam trap: SSML is not required for basic TTS; plain text input works for simple use cases. SSML is used when you need fine-grained control over how specific words or sentences are spoken, such as in customer-facing voice experiences.</p>" },
  { id: "n20", deck: "NLP \u0026 Speech", tag: "Speech", front: "Speech translation", back: "<p><strong>Speech translation</strong> in Azure AI Speech converts spoken audio in one language directly to text or synthesized speech in another language in real time, combining ASR and neural machine translation.</p><p class=\"faint\">Exam trap: speech translation is a combined ASR + translation pipeline in a single SDK call. It is not the same as first transcribing speech with Azure AI Speech and then separately calling Azure AI Translator on the text.</p>" },
  { id: "n21", deck: "NLP \u0026 Speech", tag: "Speech", front: "Speaker recognition", back: "<p><strong>Speaker recognition</strong> in Azure AI Speech verifies the identity of a speaker (speaker verification) or determines who is speaking among a known set of individuals (speaker identification) based on voice characteristics.</p><p class=\"faint\">Exam trap: speaker recognition uses voice as a biometric, similar to face recognition using face images. Speaker verification is 1:1; speaker identification is 1:N. Both require enrollment of reference voice samples.</p>" },
  { id: "n22", deck: "NLP \u0026 Speech", tag: "Speech", front: "Batch transcription", back: "<p><strong>Batch transcription</strong> is an Azure AI Speech capability for asynchronously transcribing large volumes of pre-recorded audio files stored in Azure Blob Storage, returning transcripts as files when complete.</p><p class=\"faint\">Exam trap: batch transcription is asynchronous and designed for large datasets of audio files; it is not suitable for real-time interactive applications. Use real-time speech to text for live transcription scenarios.</p>" },
  { id: "n23", deck: "NLP \u0026 Speech", tag: "Translation", front: "Neural machine translation (NMT)", back: "<p><strong>Neural machine translation (NMT)</strong> uses deep learning models to convert text from one language to another. Azure AI Translator is Microsoft\u2019s NMT service, supporting over 100 languages via REST API for text, documents, and dictionary lookup.</p><p class=\"faint\">Exam trap: Azure AI Translator handles text-based translation; Azure AI Speech handles spoken-audio translation. They are separate services but can be combined in the Speech SDK for end-to-end speech translation pipelines.</p>" },
  { id: "n24", deck: "NLP \u0026 Speech", tag: "Translation", front: "Transliteration", back: "<p><strong>Transliteration</strong> converts text from one writing script to another without translating the language\u2014for example, converting Russian Cyrillic text to Latin script so an English speaker can read it phonetically.</p><p class=\"faint\">Exam trap: transliteration changes the script; translation changes the language. Transliterating \"Moskva\" to \"Moscow\" in Latin script is transliteration. Translating it to \"Moscow\" in English meaning is translation.</p>" },
  { id: "n25", deck: "NLP \u0026 Speech", tag: "NLP", front: "NER vs. PII detection", back: "<p><strong>Named entity recognition (NER)</strong> identifies entities of general categories (person, location, organization, date); <strong>PII detection</strong> is a specialized NER that focuses specifically on sensitive personal information that must be protected or redacted.</p><p class=\"faint\">Exam trap: PII detection is built on top of NER but returns additional privacy-relevant entity types (SSN, passport numbers) and supports redaction. Use PII detection specifically when your goal is data protection compliance.</p>" },
  { id: "n26", deck: "NLP \u0026 Speech", tag: "NLP", front: "Extractive vs. abstractive summarization", back: "<p><strong>Extractive summarization</strong> copies important sentences verbatim from the source; <strong>abstractive summarization</strong> generates a new, often shorter summary using words not necessarily in the original, produced by a language model.</p><p class=\"faint\">Exam trap: extractive summaries are always faithful to the source (no hallucination possible). Abstractive summaries may be more readable but can introduce subtle inaccuracies. Choose based on whether fidelity or fluency is more important.</p>" },
  { id: "g1", deck: "Generative AI", tag: "Concepts", front: "Generative AI", back: "<p><strong>Generative AI</strong> refers to AI models that produce new content\u2014text, images, audio, or code\u2014by learning patterns from training data, rather than classifying or predicting existing inputs.</p><p class=\"faint\">Exam trap: generative AI creates new content; discriminative AI predicts labels or values for existing inputs. A model that writes a product description is generative; a model that classifies a review as positive is discriminative.</p>" },
  { id: "g2", deck: "Generative AI", tag: "LLM", front: "Large language model (LLM)", back: "<p>A <strong>large language model (LLM)</strong> is a deep learning model trained on massive text corpora using the Transformer architecture to generate coherent, contextually appropriate text. GPT-4o is an example.</p><p class=\"faint\">Exam trap: LLMs are probabilistic text predictors, not factual truth engines. Their outputs are statistically plausible, which is why they hallucinate plausible-sounding but incorrect facts.</p>" },
  { id: "g3", deck: "Generative AI", tag: "LLM", front: "Token", back: "<p>A <strong>token</strong> is the basic unit of text that an LLM processes. Tokens may be whole words, word fragments, or characters. Both prompt and completion are measured and billed in tokens.</p><p class=\"faint\">Exam trap: pricing, context window limits, and throughput quotas in Azure OpenAI are all measured in tokens, not words or characters. One English word is roughly 1-2 tokens on average.</p>" },
  { id: "g4", deck: "Generative AI", tag: "Prompting", front: "Prompt", back: "<p>A <strong>prompt</strong> is the text input provided to an LLM that instructs or queries the model. The quality of the prompt directly influences the usefulness and accuracy of the response.</p><p class=\"faint\">Exam trap: the full prompt includes the system message and conversation history, not just the latest user message. Prompt engineering is the discipline of crafting inputs to produce better outputs.</p>" },
  { id: "g5", deck: "Generative AI", tag: "LLM", front: "Completion", back: "<p>A <strong>completion</strong> is the text output generated by an LLM in response to a prompt. Azure OpenAI returns completions from models such as GPT-4o via a REST API or SDK.</p><p class=\"faint\">Exam trap: the older \u0022completions\u0022 endpoint is for text-only tasks; \u0022chat completions\u0022 is the modern conversational endpoint. Most current use cases should use the chat completions endpoint.</p>" },
  { id: "g6", deck: "Generative AI", tag: "LLM", front: "Context window", back: "<p>The <strong>context window</strong> is the maximum number of tokens an LLM can process in a single call (prompt plus completion combined). Content beyond the context window is not visible to the model.</p><p class=\"faint\">Exam trap: long documents exceeding the context window must be chunked or retrieved selectively with RAG. The model cannot consider content it cannot see within its window.</p>" },
  { id: "g7", deck: "Generative AI", tag: "Prompting", front: "Temperature", back: "<p><strong>Temperature</strong> controls the randomness of an LLM output. Low temperature (near 0) produces deterministic, focused responses; high temperature (near 1 or above) produces more varied, creative responses.</p><p class=\"faint\">Exam trap: temperature controls randomness, not accuracy. For factual extraction or summarization, use low temperature. For creative writing, a higher temperature is appropriate.</p>" },
  { id: "g8", deck: "Generative AI", tag: "Prompting", front: "Top-p sampling", back: "<p><strong>Top-p</strong> (nucleus sampling) restricts the model to the smallest set of tokens whose cumulative probability meets or exceeds p. Lower top-p means more predictable output.</p><p class=\"faint\">Exam trap: temperature and top-p both control output diversity. Microsoft recommends adjusting one but not both simultaneously, as their combined effect can be unpredictable.</p>" },
  { id: "g9", deck: "Generative AI", tag: "LLM", front: "Hallucination", back: "<p>A <strong>hallucination</strong> occurs when an LLM generates confident-sounding text that is factually wrong or entirely fabricated, such as inventing a citation or a historical event that does not exist.</p><p class=\"faint\">Exam trap: hallucinations are an inherent property of LLMs, not a simple bug. Key mitigations include grounding via RAG, clear system message instructions, and post-generation verification steps.</p>" },
  { id: "g10", deck: "Generative AI", tag: "Prompting", front: "Prompt engineering", back: "<p><strong>Prompt engineering</strong> is the discipline of crafting and iterating on prompts to elicit accurate, useful, and safe responses from an LLM without modifying the model\u2019s weights.</p><p class=\"faint\">Exam trap: prompt engineering changes only the input; fine-tuning changes the model weights. Prompt engineering is cheaper and faster to iterate on and should be tried before investing in fine-tuning.</p>" },
  { id: "g11", deck: "Generative AI", tag: "Prompting", front: "System message", back: "<p>A <strong>system message</strong> is a special prompt placed at the start of a chat conversation that sets the model\u2019s persona, scope, and behavioral constraints before any user messages, ensuring consistent and safe responses.</p><p class=\"faint\">Exam trap: the system message is the primary mechanism for customizing LLM behavior in Azure OpenAI. It should instruct the model to stay on topic and decline requests outside its defined scope.</p>" },
  { id: "g12", deck: "Generative AI", tag: "Prompting", front: "Zero-shot vs. few-shot prompting", back: "<p><strong>Zero-shot prompting</strong> asks the model to perform a task with no examples; <strong>few-shot prompting</strong> includes a small number of input-output examples in the prompt to demonstrate the desired output format before the actual query.</p><p class=\"faint\">Exam trap: few-shot provides examples at inference time inside the prompt; fine-tuning trains the model on many examples to update its weights. They are distinct techniques with very different costs.</p>" },
  { id: "g13", deck: "Generative AI", tag: "RAG", front: "Grounding", back: "<p><strong>Grounding</strong> is the practice of providing an LLM with authoritative, relevant factual context in the prompt so its response is anchored in real, current information rather than solely in training data.</p><p class=\"faint\">Exam trap: grounding reduces hallucination by giving the model source material to cite. Without grounding, the model may generate plausible-sounding but outdated or fabricated answers. RAG is the primary grounding pattern on Azure.</p>" },
  { id: "g14", deck: "Generative AI", tag: "RAG", front: "Retrieval augmented generation (RAG)", back: "<p><strong>Retrieval augmented generation (RAG)</strong> is a pattern where a retrieval step fetches relevant document chunks from a search index and injects them into the LLM prompt, enabling accurate answers from custom knowledge without retraining.</p><p class=\"faint\">Exam trap: RAG does not change model weights; it augments the prompt with retrieved text. Azure AI Search is the common retrieval layer. RAG is preferable to fine-tuning when current factual knowledge is needed.</p>" },
  { id: "g15", deck: "Generative AI", tag: "RAG", front: "Embedding", back: "<p>An <strong>embedding</strong> is a dense numerical vector representing the semantic meaning of a text fragment. Texts with similar meanings have vectors close together in vector space, enabling semantic similarity search.</p><p class=\"faint\">Exam trap: embeddings are numerical vectors, not raw text. Azure OpenAI provides embedding models (e.g., text-embedding-3-small) to convert text into vectors for storage in a vector index used by RAG pipelines.</p>" },
  { id: "g16", deck: "Generative AI", tag: "RAG", front: "Vector search", back: "<p><strong>Vector search</strong> finds documents whose embeddings are most similar to a query embedding using metrics such as cosine similarity, enabling semantic search that understands meaning rather than matching keywords.</p><p class=\"faint\">Exam trap: keyword search matches exact terms; vector search matches semantic meaning. Azure AI Search supports both vector and hybrid search, making it the common retrieval layer in RAG solutions on Azure.</p>" },
  { id: "g17", deck: "Generative AI", tag: "LLM", front: "Fine-tuning", back: "<p><strong>Fine-tuning</strong> updates an LLM\u2019s weights by continuing training on a smaller domain-specific dataset so the model reliably follows a specific output format, style, or domain vocabulary without requiring examples in every prompt.</p><p class=\"faint\">Exam trap: fine-tuning is expensive and time-consuming. Use it when the model needs a consistent output style or structure. For providing up-to-date factual knowledge, RAG is more appropriate and easier to maintain.</p>" },
  { id: "g18", deck: "Generative AI", tag: "LLM", front: "Fine-tuning vs. RAG", back: "<p><strong>Fine-tuning</strong> is best for teaching a consistent output style, structured format, or domain vocabulary. <strong>RAG</strong> is best for providing current or proprietary factual knowledge without retraining the model.</p><p class=\"faint\">Exam trap: a scenario where the model must answer questions about internal product documentation points to RAG, not fine-tuning. RAG is cheaper, faster to update, and more transparent about its source material.</p>" },
  { id: "g19", deck: "Generative AI", tag: "LLM", front: "Multi-modal model", back: "<p>A <strong>multi-modal model</strong> is an AI model that can process and generate multiple types of data beyond text, such as images and audio in the same context. GPT-4o can process both text and images.</p><p class=\"faint\">Exam trap: multi-modal refers to different data types (text, image, audio), not multiple languages. A model that supports French and English is multilingual; one that handles text and images is multi-modal.</p>" },
  { id: "g20", deck: "Generative AI", tag: "LLM", front: "DALL-E and image generation", back: "<p><strong>DALL-E</strong> is an Azure OpenAI image generation model that creates original images from natural-language text descriptions. It supports image creation, inpainting, and generating variations of existing images.</p><p class=\"faint\">Exam trap: DALL-E generates new images from text prompts; Azure AI Vision analyzes existing images. DALL-E is generative (creates content); Azure AI Vision is analytical (interprets content). Do not confuse them.</p>" },
  { id: "g21", deck: "Generative AI", tag: "LLM", front: "Whisper (Azure OpenAI)", back: "<p><strong>Whisper</strong> is an Azure OpenAI speech-to-text model that transcribes and optionally translates audio across many languages with high accuracy across diverse accents and audio quality levels.</p><p class=\"faint\">Exam trap: Whisper is accessed via Azure OpenAI Service, not Azure AI Speech. Both provide transcription, but Azure AI Speech offers more real-time options and customization. Whisper is a simpler model endpoint billed per token.</p>" },
  { id: "g22", deck: "Generative AI", tag: "Copilot", front: "Copilot", back: "<p>A <strong>copilot</strong> is an AI assistant built on a foundation model that helps users complete tasks by generating suggestions, content, or actions within an application, such as Microsoft 365 Copilot or GitHub Copilot.</p><p class=\"faint\">Exam trap: copilots are application-layer AI assistants built on top of LLMs; they are not standalone models. Azure AI Foundry provides tools to build custom copilots for enterprise scenarios.</p>" },
  { id: "g23", deck: "Generative AI", tag: "Agents", front: "AI agent", back: "<p>An <strong>AI agent</strong> is an LLM-based system that autonomously plans and executes multi-step tasks by calling tools, accessing data, and making decisions in pursuit of a stated goal, going beyond single-turn question answering.</p><p class=\"faint\">Exam trap: an AI agent uses tools and memory across multiple steps; a simple chatbot responds to single questions without planning. Agents require guardrails and human oversight for high-stakes decisions.</p>" },
  { id: "g24", deck: "Generative AI", tag: "Agents", front: "Plugin and tool calling", back: "<p><strong>Tool calling</strong> (also called function calling or plugins) allows an LLM to invoke external functions, APIs, or services during generation, enabling it to retrieve live data, perform calculations, or take real-world actions.</p><p class=\"faint\">Exam trap: tool calling executes code or APIs at runtime. It is not RAG (which injects text into the prompt) nor fine-tuning (which updates weights). Tool calling enables the agentic behavior where the model drives actions.</p>" },
  { id: "g25", deck: "Generative AI", tag: "Foundry", front: "Model catalog (Azure AI Foundry)", back: "<p>The <strong>model catalog</strong> in Azure AI Foundry is a curated library of foundation models from Microsoft, OpenAI, Meta, Mistral, and others that can be evaluated, fine-tuned, and deployed as endpoints from a single hub.</p><p class=\"faint\">Exam trap: the model catalog includes both Azure OpenAI models and third-party open-source models. Not all models support all deployment methods; check whether a model supports serverless API or requires managed compute.</p>" },
  { id: "g26", deck: "Generative AI", tag: "Foundry", front: "Serverless API deployment", back: "<p><strong>Serverless API deployment</strong> in Azure AI Foundry deploys foundation models as pay-per-token APIs without provisioning compute infrastructure. You are billed only for the tokens consumed.</p><p class=\"faint\">Exam trap: serverless deployment is easier to start and has no idle costs, but uses shared multi-tenant infrastructure. For data isolation or predictable throughput, use managed compute deployment instead.</p>" },
  { id: "g27", deck: "Generative AI", tag: "Foundry", front: "Managed compute deployment", back: "<p><strong>Managed compute deployment</strong> in Azure AI Foundry provisions dedicated virtual machine infrastructure to host a model, providing data isolation, consistent throughput, and support for models unavailable as serverless APIs.</p><p class=\"faint\">Exam trap: managed compute is more expensive than serverless due to always-on VM costs, but provides dedicated capacity and stronger isolation for sensitive enterprise workloads.</p>" },
  { id: "g28", deck: "Generative AI", tag: "Safety", front: "Content filter severity levels", back: "<p>Azure OpenAI <strong>content filter severity levels</strong> classify harmful content at four levels: 0 (safe), 2 (low), 4 (medium), 6 (high), for each category: hate, violence, sexual, and self-harm. Filters apply to both prompts and completions.</p><p class=\"faint\">Exam trap: the default configuration blocks medium and high severity. Lowering thresholds requires a Microsoft-approved exception. Content filters are a runtime safety layer, not a training-time fix.</p>" },
  { id: "g29", deck: "Generative AI", tag: "Safety", front: "Prompt shields and jailbreak detection", back: "<p><strong>Prompt shields</strong> in Azure AI Content Safety detect and block jailbreak attempts (users trying to bypass safety instructions) and indirect prompt injection attacks (malicious instructions embedded in documents the model reads).</p><p class=\"faint\">Exam trap: content filters catch harmful output categories (hate, violence); prompt shields catch attempts to subvert the system message or safety guardrails themselves. They are complementary, not redundant, safety layers.</p>" },
  { id: "g30", deck: "Generative AI", tag: "Safety", front: "Identify-measure-mitigate-operate process", back: "<p>Microsoft\u2019s responsible generative AI process has four stages: <strong>Identify</strong> potential harms, <strong>Measure</strong> their frequency and severity, <strong>Mitigate</strong> with layered controls (model, system, UX, operations), and <strong>Operate</strong> with monitoring and incident response.</p><p class=\"faint\">Exam trap: measurement must precede mitigation so you know which harms are actually present before choosing controls. This four-stage process applies to all generative AI solutions on Azure.</p>" },
  { id: "s1", deck: "Azure AI Services", tag: "Services", front: "Multi-service vs. single-service resource", back: "<p>An <strong>Azure AI Services multi-service resource</strong> provides access to multiple Azure AI capabilities (vision, language, speech, etc.) under a single key and endpoint. A <strong>single-service resource</strong> is dedicated to one service (e.g., Azure AI Vision only) with its own key.</p><p class=\"faint\">Exam trap: a multi-service resource simplifies billing and key management but does not offer per-service pricing granularity. Use single-service resources when you need service-level access controls or separate billing.</p>" },
  { id: "s2", deck: "Azure AI Services", tag: "Services", front: "Keys and endpoints", back: "<p>Azure AI Services authenticate calls using a <strong>key</strong> (a secret token included in the request header) and an <strong>endpoint</strong> (the URL for the service). Each resource has two keys to allow zero-downtime key rotation.</p><p class=\"faint\">Exam trap: keys are secrets and must not be embedded in client-side code or committed to source control. Use Azure Key Vault to store keys securely and managed identity to avoid key-based authentication entirely.</p>" },
  { id: "s3", deck: "Azure AI Services", tag: "Foundry", front: "Azure AI Foundry portal", back: "<p>The <strong>Azure AI Foundry portal</strong> (formerly Azure AI Studio) is the unified web interface for building, evaluating, and deploying AI applications using foundation models, Azure AI Services, and Azure Machine Learning capabilities.</p><p class=\"faint\">Exam trap: Azure AI Foundry portal is for AI application development (generative AI, copilots, evaluations); Azure Machine Learning studio is for traditional ML model training and MLOps. They are separate portals with different focus areas.</p>" },
  { id: "s4", deck: "Azure AI Services", tag: "Foundry", front: "Azure AI Foundry project", back: "<p>An <strong>Azure AI Foundry project</strong> is a workspace within a hub that contains the resources, models, deployments, evaluations, and connections for a specific AI application or team, providing isolation and access control.</p><p class=\"faint\">Exam trap: a project lives inside a hub. The hub manages shared infrastructure (compute, connections, governance); projects inherit the hub\u2019s settings but can have their own members, deployments, and data.</p>" },
  { id: "s5", deck: "Azure AI Services", tag: "Foundry", front: "Azure AI Foundry hub", back: "<p>An <strong>Azure AI Foundry hub</strong> is the top-level organizational container in Azure AI Foundry that manages shared compute, connections to Azure resources, security policies, and governance for one or more projects.</p><p class=\"faint\">Exam trap: one hub can host many projects. The hub is analogous to an Azure Machine Learning workspace in that it provides shared infrastructure. Projects within a hub share the hub\u2019s network and security settings.</p>" },
  { id: "s6", deck: "Azure AI Services", tag: "Foundry", front: "Playgrounds (Azure AI Foundry)", back: "<p><strong>Playgrounds</strong> in Azure AI Foundry are interactive, no-code testing environments where developers can experiment with foundation models, adjust parameters, test prompts, and evaluate responses before writing any application code.</p><p class=\"faint\">Exam trap: playgrounds are for rapid experimentation and do not require deploying a model first (for serverless models). They are not for production use; results from the playground must be replicated in application code.</p>" },
  { id: "s7", deck: "Azure AI Services", tag: "Foundry", front: "Prompt flow", back: "<p><strong>Prompt flow</strong> in Azure AI Foundry is a development tool for building, testing, and deploying LLM-based application workflows as directed acyclic graphs of nodes (prompts, Python code, tools), making complex AI pipelines reproducible.</p><p class=\"faint\">Exam trap: prompt flow is for orchestrating multi-step LLM workflows (RAG pipelines, chain-of-thought reasoning); it is not a general-purpose workflow tool. Think of it as a visual notebook for LLM applications.</p>" },
  { id: "s8", deck: "Azure AI Services", tag: "Foundry", front: "Evaluations (Azure AI Foundry)", back: "<p><strong>Evaluations</strong> in Azure AI Foundry are automated assessments of a generative AI application\u2019s outputs against quality and safety metrics (groundedness, relevance, coherence, fluency, safety), helping identify issues before deployment.</p><p class=\"faint\">Exam trap: evaluations measure output quality using AI-assisted grading and predefined metrics. They are distinct from A/B testing in production; evaluations run offline on test datasets before the model is deployed.</p>" },
  { id: "s9", deck: "Azure AI Services", tag: "OpenAI", front: "Azure OpenAI Service", back: "<p><strong>Azure OpenAI Service</strong> provides access to OpenAI\u2019s language and image models (GPT-4o, DALL-E, Whisper, embeddings) via Azure infrastructure with enterprise security, compliance, and data residency guarantees.</p><p class=\"faint\">Exam trap: Azure OpenAI Service is not the same as using the public OpenAI API. Azure OpenAI data stays within your Azure tenant and does not train OpenAI\u2019s models. It requires a separate access request and quota.</p>" },
  { id: "s10", deck: "Azure AI Services", tag: "OpenAI", front: "Azure OpenAI deployment", back: "<p>An <strong>Azure OpenAI deployment</strong> is a named instance of a model (e.g., a GPT-4o deployment) created within an Azure OpenAI resource, providing a dedicated endpoint and quota allocation for that model version.</p><p class=\"faint\">Exam trap: you must create a deployment before calling a model; referencing the model name alone (e.g., \u0022gpt-4o\u0022) is not sufficient. Each deployment has its own tokens-per-minute quota limit.</p>" },
  { id: "s11", deck: "Azure AI Services", tag: "OpenAI", front: "Quota and tokens per minute (TPM)", back: "<p><strong>Quota</strong> in Azure OpenAI is the maximum rate of token consumption allowed for a deployment, measured in <strong>tokens per minute (TPM)</strong>. Exceeding the quota returns HTTP 429 (too many requests).</p><p class=\"faint\">Exam trap: TPM quota is per deployment, not per account. If multiple deployments share the same model, they each have separate TPM limits. Increasing quota requires a request to Microsoft.</p>" },
  { id: "s12", deck: "Azure AI Services", tag: "OpenAI", front: "On-your-data (Azure OpenAI)", back: "<p><strong>On-your-data</strong> is an Azure OpenAI feature that connects a GPT model directly to an Azure AI Search index so the model answers questions using your own documents as grounding context, implementing RAG without custom code.</p><p class=\"faint\">Exam trap: on-your-data is a managed RAG integration, not custom RAG code. It is convenient for quick deployments but gives less control than building a custom RAG pipeline with prompt flow.</p>" },
  { id: "s13", deck: "Azure AI Services", tag: "Safety", front: "Azure AI Content Safety", back: "<p><strong>Azure AI Content Safety</strong> is a standalone Azure AI service that detects harmful content (hate, violence, sexual, self-harm) in text and images, and provides prompt shields for jailbreak detection, independent of any specific model.</p><p class=\"faint\">Exam trap: Azure AI Content Safety is a separate service from Azure OpenAI\u2019s built-in content filters. You can use it to add safety checks to any AI application, not just Azure OpenAI-based ones.</p>" },
  { id: "s14", deck: "Azure AI Services", tag: "Search", front: "Azure AI Search (for RAG)", back: "<p><strong>Azure AI Search</strong> (formerly Azure Cognitive Search) is a cloud search service that indexes content from various sources and provides full-text, semantic, and vector search. It is the primary retrieval layer in Azure RAG solutions.</p><p class=\"faint\">Exam trap: Azure AI Search is not limited to AI scenarios; it also serves as a general enterprise search engine. In RAG, it stores document embeddings and performs vector similarity search to find relevant chunks for the LLM prompt.</p>" },
  { id: "s15", deck: "Azure AI Services", tag: "Language", front: "Azure AI Language", back: "<p><strong>Azure AI Language</strong> is the Azure AI service for NLP tasks including sentiment analysis, key phrase extraction, NER, PII detection, summarization, question answering, CLU, and custom text classification, all accessible via a single REST API.</p><p class=\"faint\">Exam trap: Azure AI Language replaced multiple legacy services (Text Analytics, LUIS, QnA Maker). If the exam mentions any of those older names, map them to Azure AI Language for current capabilities.</p>" },
  { id: "s16", deck: "Azure AI Services", tag: "Speech", front: "Azure AI Speech", back: "<p><strong>Azure AI Speech</strong> is the Azure AI service providing speech to text, text to speech, speech translation, speaker recognition, and custom neural voice, accessible via SDK or REST API for real-time and batch audio processing.</p><p class=\"faint\">Exam trap: Azure AI Speech is a dedicated speech service; Whisper in Azure OpenAI is a separate model endpoint. Azure AI Speech supports real-time streaming and custom acoustic models that Whisper does not.</p>" },
  { id: "s17", deck: "Azure AI Services", tag: "Vision", front: "Azure AI Vision", back: "<p><strong>Azure AI Vision</strong> is the Azure AI service for image and video analysis, providing image classification, object detection, OCR (Read API), captions, tags, face detection, smart crop, and background removal via REST API.</p><p class=\"faint\">Exam trap: Azure AI Vision uses Microsoft pretrained models; Azure AI Custom Vision trains models on your own labeled images. Use the right service based on whether your use case fits a general model or requires custom training.</p>" },
  { id: "s18", deck: "Azure AI Services", tag: "Face", front: "Azure AI Face", back: "<p><strong>Azure AI Face</strong> is the Azure AI service for face detection, face analysis (attributes), face verification, and face identification. Some capabilities (identification, verification) are subject to the Limited Access policy.</p><p class=\"faint\">Exam trap: face detection and attribute analysis are open access; face identification and verification require Limited Access approval. Always check gating requirements before designing a solution that uses recognition features.</p>" },
  { id: "s19", deck: "Azure AI Services", tag: "Translation", front: "Azure AI Translator", back: "<p><strong>Azure AI Translator</strong> is the Azure AI service for neural machine translation of text and documents across 100+ languages, supporting real-time translation, document translation, dictionary lookup, and language detection.</p><p class=\"faint\">Exam trap: Azure AI Translator translates text; Azure AI Speech translates spoken audio. Transliteration (script conversion) is a separate capability within Azure AI Translator, not a separate service.</p>" },
  { id: "s20", deck: "Azure AI Services", tag: "Document", front: "Azure AI Document Intelligence", back: "<p><strong>Azure AI Document Intelligence</strong> (formerly Form Recognizer) extracts structured data from documents using prebuilt models for common document types and custom models for proprietary forms, going beyond plain OCR.</p><p class=\"faint\">Exam trap: Azure AI Document Intelligence understands document structure and semantics (fields, tables, signatures); plain OCR just reads characters. Use Document Intelligence when you need to extract specific named fields from business documents.</p>" },
  { id: "s21", deck: "Azure AI Services", tag: "Bots", front: "Azure AI Bot Service", back: "<p><strong>Azure AI Bot Service</strong> is a managed platform for building, hosting, and connecting chatbots and virtual agents to multiple channels (Teams, web chat, telephony) using the Bot Framework SDK or Power Virtual Agents.</p><p class=\"faint\">Exam trap: Azure AI Bot Service manages the hosting and channel integration; Azure AI Language (CLU, question answering) provides the intelligence. They work together: Bot Service handles the dialog; Language handles understanding.</p>" },
  { id: "s22", deck: "Azure AI Services", tag: "Pricing", front: "Free vs. standard pricing tier", back: "<p>Most Azure AI Services offer a <strong>free tier</strong> with limited monthly transactions (no charge, no SLA) suitable for development and testing, and a <strong>standard tier</strong> with pay-per-use pricing, SLA guarantees, and higher or unlimited transaction volumes for production.</p><p class=\"faint\">Exam trap: the free tier has no SLA and rate limits that make it unsuitable for production. Always deploy production workloads on the standard tier. Some capabilities (e.g., custom neural voice) are only available in the standard tier.</p>" }
];

